for(const [language,items]of Object.entries({"ko":{"missionBoard":"출항 임무판","missionBoardNote":"완료한 임무는 독립된 출항으로 다시 도전할 수 있습니다. 실패해도 구조 기록은 유지됩니다.","missionDone":"구조 완료","missionNext":"다음 출항","missionLocked":"이전 구조 후 열림","missionReplay":"다시 출항","missionSelect":"임무 보기","recordContacts":"접촉","recordBest":"최고 무손상","marketTitle":"시장 뒤편","marketBrief":"시장 분지에 승객선이 남았습니다. 짧은 서쪽 출구는 빈 얼음 운반선이 막고 있습니다. 운반선을 포켓에 옮겨 묶거나, 승객선을 동쪽의 넓은 횡류 수로로 데려오세요.","marketPower":"전원함을 자르면 두 물살과 최종 접안 윈치가 함께 멈춥니다. 포켓 계류에는 전력이 필요하지 않습니다. 얼음선을 움직이지 않아도 구조할 수 있습니다.","marketComplete":"배달 명단의 사람들이 돌아왔다","marketRecord":"매옥은 얼음 배달판에 대피자 이름을 적어 두었습니다. 늦은 버스는 터미널 명단에서 빠진 이들을 태우러 왔습니다. 다음 미응답 장소는 배수문 펌프조입니다.","marketOutcome":"승객들이 남쪽 안전 부두로 내렸습니다. 매옥은 젖은 앞치마를 접고 도시락 가방 옆에서 명단을 다시 확인합니다.","marketPassenger":"시장 승객선","marketIce":"빈 얼음 운반선","marketPassengerLine":"승객선 사고 계류선","marketIceLine":"얼음선 사고 계류선","marketIcePocket":"얼음선 안전 계류 포켓","marketHall":"해문 새벽시장","marketNames":"매옥의 배달 명단","marketGantry":"얼음 적재 갠트리","marketDrain":"서쪽 배수 조작","marketUnmoor":"Q로 해당 사고 계류선을 감싸 자르세요","marketChoose":"서쪽을 정리하거나 동쪽으로 승객선을 데려오세요","marketTowIce":"얼음선을 서쪽 포켓으로 옮기세요 — 선택 사항","marketTowPassenger":"승객선을 남쪽 안전 부두로 예인하세요","marketRouteHint":"짧은 서쪽은 얼음선 정리가 필요합니다. 넓은 동쪽은 횡류가 있습니다.","marketIceHint":"포켓의 화살표대로 저속으로 대세요. E로 현재 자세에 묶고, 선수 고리 근처에서 E로 풀 수 있습니다.","towActionMoor":"E · 안전 계류","towActionUnmoor":"E · 임시 계류 풀기","towActionMoorFast":"E · 분리 / 계류는 저속에서","towActionMoorHeading":"E · 분리 / 계류 방향을 맞추세요","towActionMoorBow":"E · 분리 / 계류는 선수 가까이","moored":"현재 자세로 계류했습니다. 예인정은 자유롭게 움직일 수 있습니다.","unmoored":"임시 계류를 풀었습니다. E로 예인줄을 다시 연결하세요.","moorFast":"저속에서 계류할 수 있습니다.","moorHeading":"포켓 화살표 방향으로 선체를 맞추세요.","moorBow":"선체를 포켓 안에 두고 선수 고리를 계선주 가까이 대세요.","cargoSecured":"부교가 안전하게 고정되었습니다.","contentTowGuide":"안전 계류 포켓: 긴 선체 전체를 표시 안에 넣고 화살표 방향으로 저속 접근하세요. E는 현재 위치에 묶으며 순간이동하지 않습니다. 선수 고리에서 E로 풀고 다시 연결할 수 있습니다."},"en":{"missionBoard":"Dispatch board","missionBoardNote":"Replay completed jobs as independent departures. Failed retries keep the people and records already saved.","missionDone":"Rescue complete","missionNext":"Next departure","missionLocked":"After the previous rescue","missionReplay":"Replay departure","missionSelect":"View mission","recordContacts":"Contacts","recordBest":"Best undamaged","marketTitle":"Behind the Market","marketBrief":"Passengers remain in the market basin. An empty ice carrier obstructs the short western exit. Move it into the side pocket and moor it, or take the passenger boat through the broad eastern crosscurrent.","marketPower":"Cutting the power box stops both currents and the final docking winch. Temporary mooring needs no power. Moving the ice carrier is optional.","marketComplete":"The names on the delivery board","marketRecord":"Mae-ok wrote evacuees' names on her ice-delivery board. The late bus had come for people missing from the terminal list. The next unanswered call is from the sluice pump crew.","marketOutcome":"The passengers stepped onto the southern safe pier. Mae-ok folds her wet apron and checks the list beside a lunch bag.","marketPassenger":"Market passenger boat","marketIce":"Empty ice carrier","marketPassengerLine":"Passenger mooring line","marketIceLine":"Ice carrier mooring line","marketIcePocket":"Ice carrier mooring pocket","marketHall":"HAEMUN DAWN MARKET","marketNames":"Mae-ok's delivery list","marketGantry":"ICE LOADING GANTRY","marketDrain":"Western drain control","marketUnmoor":"Enclose the accident mooring line with Q to cut it","marketChoose":"Clear the west, or bring the passenger boat around the east","marketTowIce":"Move the ice carrier to the western pocket — optional","marketTowPassenger":"Tow the passengers to the southern safe pier","marketRouteHint":"The short west needs room cleared. The broad east has a crosscurrent.","marketIceHint":"Approach slowly in the pocket's arrow direction. E moors the current pose; E by the bow ring releases it.","towActionMoor":"E · Moor here","towActionUnmoor":"E · Release temporary mooring","towActionMoorFast":"E · Detach / slow down to moor","towActionMoorHeading":"E · Detach / align to moor","towActionMoorBow":"E · Detach / bring bow closer","moored":"Moored at the current pose. The tug is free to move.","unmoored":"Temporary mooring released. Press E again to connect the towline.","moorFast":"Slow down before mooring.","moorHeading":"Point the hull along the pocket arrow.","moorBow":"Keep the entire hull inside and bring the bow ring near the bollard.","cargoSecured":"The pontoon is safely installed.","contentTowGuide":"Temporary pocket: fit the whole hull inside, follow its arrow, and slow down. E secures the current pose without snapping. Return to the bow ring, release with E, then connect the towline."}}))Object.assign(rescueText[language],items);
for(const [language,items]of Object.entries({"ko":{"marketArrival":["매옥 · 시장 상인","얼음 배달판에 이름을 적어 뒀어요. 그 명단에 있는 사람들은 아직 이 배에 있어요."],"marketCutHint":"사고 계류선은 Q 삼각형으로 절단합니다. 선수 고리에는 E로 연결하며 선체끼리 닿지 않아도 됩니다.","marketRouteGuide":"시장에는 승객선과 빈 얼음 운반선이 있습니다. 서쪽을 쓰려면 얼음선을 옆 포켓으로 옮기세요. 동쪽 횡류 수로로 가면 얼음선을 그대로 둘 수 있습니다."},"en":{"marketArrival":["Mae-ok · market trader","I wrote the names on the ice-delivery board. The people on that list are still on this boat."],"marketCutHint":"Cut accident mooring lines with a Q triangle. E connects near a bow ring; hull contact is not needed.","marketRouteGuide":"The market has a passenger boat and an empty ice carrier. Move the carrier into its pocket to use the west. The eastern crosscurrent route lets you leave it where it is."}})){rescueText[language].radio.marketArrival=items.marketArrival;rescueText[language].marketCutHint=items.marketCutHint;rescueText[language].marketRouteGuide=items.marketRouteGuide;}
for(const [language,items]of Object.entries({"ko":{"marketLaunch":"시장으로 출항","marketPassengerFree":["윤해수","승객선 계류선은 풀렸어. 서쪽을 정리하거나 동쪽으로 돌아가면 돼."],"marketIceFree":["윤해수","얼음선이 풀렸어. 포켓에 묶으면 서쪽 길이 열려."],"marketMapLegend":"● 승객선  ·  ○ 얼음선","marketApproach":"북쪽 승객선 / 서쪽 얼음선"},"en":{"marketLaunch":"Depart for the market","marketPassengerFree":["Yoon Haesu","The passenger line is free. Clear the west or take the east around."],"marketIceFree":["Yoon Haesu","Ice carrier free. Moor it in the pocket to open the west."],"marketMapLegend":"● Passengers  ·  ○ Ice carrier","marketApproach":"Passengers north / ice carrier west"}})){for(const [key,value]of Object.entries(items)){if(Array.isArray(value))rescueText[language].radio[key]=value;else rescueText[language][key]=value;}}
rescueText.ko.towRecord="06:30 대피 완료 방송, 06:47 출항 대기. 접안한 승객이 시장 뒤편에 명단에 없는 배가 더 있다고 알려 줍니다. 다음 미응답 장소는 시장 분지입니다.";
rescueText.en.towRecord="Official evacuation complete: 06:30. Departure pending: 06:47. A passenger points us to another boat missing from the list. The next unanswered call is behind the market.";

for(const [language,items]of Object.entries({"ko":{"sluiceTitle":"수문 아래","sluiceBrief":"서쪽 수조에 점검선과 펌프 작업자들이 남았습니다. 배수 상태는 출구를 밀어 주지만 중앙에서는 남쪽 방파제로 흐릅니다. 북쪽 부두 뒤에 잠시 계류하고 동쪽 제어 잔교에서 완화 상태로 바꾸거나, 현재 물살을 읽으며 계속 예인하세요.","sluicePower":"수문은 조작한 상태를 유지합니다. 제어 잔교에서는 누구나 E로 전환할 수 있습니다. 전원함을 자르면 두 물살과 접안 윈치가 함께 멈추며 수동으로 완료할 수 있습니다.","sluiceComplete":"교대표에 남은 시간","sluiceRecord":"06:30은 철수 명단을 닫은 시각이었습니다. 06:47은 명단에서 빠진 사람들을 데리러 간 추가 운항이었습니다. 작업자는 북쪽 수리장에 아직 승객과 이동식 부잔교가 남았다고 알립니다.","sluiceOutcome":"긴 점검선이 선창에 닿자 펌프 작업자들이 차례로 내립니다. 젖은 교대표의 수리 요청란에는 이전 근무자의 서명이 겹쳐 있습니다.","sluiceLaunch":"수문으로 출항","sluiceBoat":"수문 점검선","sluiceBowLine":"점검선 선수 고정줄","sluiceSternLine":"점검선 선미 고정줄","sluicePocket":"점검선 임시 계류 포켓","sluiceControl":"수문 제어 잔교","sluiceUnmoor":"점검선의 두 고정줄을 Q 삼각형으로 자르세요","sluiceChoose":"점검선 선수 고리에 연결해 동남쪽 선창으로 이동하세요","sluiceTow":"긴 선미가 도는 공간과 중앙 물살을 확인하세요","sluiceRouteHint":"북쪽 포켓에 계류하고 수문을 바꾸거나, 열린 중앙 수로를 계속 통과하세요.","sluiceCutHint":"두 고정줄과 전원함을 구분하세요. Q의 절단 미리보기로 정확히 무엇을 자르는지 확인하세요.","sluiceGuide":"서쪽 긴 점검선을 동남쪽 선창으로 옮깁니다. 북쪽 부두 뒤 포켓은 수문을 조작하러 갈 때 배를 잡아 줍니다. 계류는 선택이며, 현재 물살을 이용하거나 전원을 끊고 갈 수도 있습니다.","sluiceControlGuide":"동쪽 제어 잔교에서 E로 배수/완화를 전환합니다. 자동으로 돌아가지 않습니다. 배수는 서쪽 출구를 돕지만 중앙을 남쪽으로 밀고, 완화는 중앙을 잠재우지만 출구를 거슬러 흐릅니다. 전원을 끊으면 물살과 접안 윈치가 멈춥니다.","sluiceControlHint":"E로 배수/완화 전환 · 예인줄은 유지됩니다","sluiceAction":"E · 수문 상태 전환","sluiceActionUnpowered":"E · 수문 위치 전환 (전원 차단)","sluiceDischargeState":"배수: 출구 순류 / 중앙 남향","sluiceReliefState":"완화: 출구 역류 / 중앙 잔잔","sluiceOff":"전원 차단: 두 물살·윈치 정지","sluiceMapLegend":"● 선박 ◆ 제어 □ 계류","sluiceYard":"해문 수문 관리소","sluiceRoster":"근무 교대표 / 수리 요청","sluiceLevel":"수위 눈금","sluicePatchedHut":"보수된 제어실","contentPeopleAshore":"탑승자들이 안전한 선창에 내렸습니다.","sluiceArrival":["펌프 작업자","명단은 여섯 시 반에 닫았어요. 수리 교대조는 그때 아직 수문 아래에 있었고요."],"sluiceOneLine":["윤해수","줄 하나 남았어. 긴 선미가 돌아가니까 남은 줄을 확인하자."],"sluiceFree":["윤해수","점검선이 풀렸어. 포켓에 잠시 묶어 수문을 바꾸거나 그대로 통과하자."],"sluiceDischarge":["펌프 작업자","배수 위치입니다. 출구는 밀어 주지만 중앙에서는 남쪽으로 흐릅니다."],"sluiceRelief":["펌프 작업자","완화 위치입니다. 중앙은 잠잠해지고 서쪽 입구에는 역류가 생깁니다."]},"en":{"sluiceTitle":"Below the Gates","sluiceBrief":"The pump crew remains aboard a long inspection boat in the western basin. Discharge helps it leave, but pushes the central water toward the southern breakwater. Moor behind the northern pier and switch to relief at the eastern control jetty, or keep towing with the current.","sluicePower":"Gate positions persist. Anyone can switch them with E at the control jetty. Cutting shared power stops both currents and the docking winch; manual completion remains possible.","sluiceComplete":"The time on the shift roster","sluiceRecord":"06:30 was when the evacuation list closed. 06:47 was an extra trip for the people omitted from it. A worker reports passengers and a movable access pontoon still at the northern repair yard.","sluiceOutcome":"The long inspection boat reaches the pier. The pump crew steps ashore with a wet shift roster, its repair requests signed by more than one shift.","sluiceLaunch":"Depart for the gates","sluiceBoat":"Inspection workboat","sluiceBowLine":"Inspection bow line","sluiceSternLine":"Inspection stern line","sluicePocket":"Inspection boat mooring pocket","sluiceControl":"Gate control jetty","sluiceUnmoor":"Cut both inspection boat moorings with a Q triangle","sluiceChoose":"Connect the inspection bow ring and head for the southeastern pier","sluiceTow":"Watch the long stern's turning room and the central current","sluiceRouteHint":"Moor in the northern pocket to switch gates, or keep moving through the central channel.","sluiceCutHint":"Separate both moorings from the power box. Check the Q cut preview before closing the triangle.","sluiceGuide":"Bring the western inspection boat to the southeastern pier. The pocket behind the northern pier holds it while you visit the gate controls. Mooring is optional: keep towing in one gate state, or cut power and dock manually.","sluiceControlGuide":"E at the eastern control jetty toggles discharge and relief without a timed reset. Discharge assists the western exit but pushes the center south. Relief calms the center but opposes the exit. Cutting power stops currents and the docking winch.","sluiceControlHint":"E toggles discharge / relief · keeps the towline","sluiceAction":"E · Switch gate position","sluiceActionUnpowered":"E · Move gate position (power cut)","sluiceDischargeState":"Discharge: exit assists / center south","sluiceReliefState":"Relief: exit opposes / center calm","sluiceOff":"Power cut: currents and winch stopped","sluiceMapLegend":"● Boat ◆ Gate □ Moor","sluiceYard":"HAEMUN GATE WORKS","sluiceRoster":"SHIFT ROSTER / REPAIR REQUESTS","sluiceLevel":"WATER LEVEL","sluicePatchedHut":"PATCHED CONTROL HUT","contentPeopleAshore":"Everyone aboard has reached the safe pier.","sluiceArrival":["Pump worker","The list closed at six thirty. Our repair shift was still below the gates."],"sluiceOneLine":["Yoon Haesu","One line remains. Watch the long stern pivot around it."],"sluiceFree":["Yoon Haesu","Inspection boat free. We can moor and change the gates, or carry on through."],"sluiceDischarge":["Pump worker","Discharge. The exit helps you, but the central flow heads south."],"sluiceRelief":["Pump worker","Relief. The center is calm, but the western entrance runs against you."]}})){for(const [key,value]of Object.entries(items)){if(Array.isArray(value))rescueText[language].radio[key]=value;else rescueText[language][key]=value;}}
for(const [language,items]of Object.entries({"ko":{"sluiceHeld":"점검선이 계류되었습니다 · 수문을 바꾸거나 돌아와 계류를 푸세요","sluiceHeldHint":"동쪽 제어 잔교에서 E로 수문을 전환할 수 있습니다. 계류 중인 배는 현재 위치를 유지합니다.","contentReleaseHint":"E로 임시 계류를 푼 다음, E를 다시 눌러 예인줄을 연결하세요.","sluiceArrivalOperator":["Woo · 펌프 작업자","Woo: 이 보수 요청, 지난 교대 때도 있었지? / 작업자: 네. 명단이 닫힌 뒤에도 남아서 끝내려 했어요. 06:47 배가 우리를 데리러 왔고요."]},"en":{"sluiceHeld":"Workboat secured · visit the controls, or return to release it","sluiceHeldHint":"E at the eastern control jetty switches the gates. The moored boat keeps its current position.","contentReleaseHint":"Press E to release the temporary mooring, then E again to connect the towline.","sluiceArrivalOperator":["Woo · pump worker","Woo: This repair was on the last shift too? / Worker: Yes. We stayed after the list closed. The 06:47 boat came back for us."]}})){for(const [key,value]of Object.entries(items)){if(Array.isArray(value))rescueText[language].radio[key]=value;else rescueText[language][key]=value;}}
for(const [language,items]of Object.entries({"ko":{"contentCoastHint":"미리 예인줄을 풀고 회전이 잦아드는지 보세요. 필요하면 다른 각도에서 다시 연결할 수 있습니다.","contentDetachedHint":"줄을 풀어도 배는 움직입니다. 선체·방향·정지 표시를 확인하고 필요하면 선수에 다시 연결하세요.","contentInertiaGuide":"예인하는 배는 길고 무겁습니다. 예인정이 멈춰도 배는 움직입니다. 넓게 돌며 선미를 보세요. 막히면 줄을 분리하고 다른 각도로 다시 연결할 수 있습니다.","contentDockBraking":"윈치가 감속 중입니다. E로 분리하고 선체에서 떨어지면 정렬을 시작합니다.","contentDockAligning":"예인정이 떨어졌습니다. 접안 윈치가 선체를 정렬하고 있습니다."},"en":{"contentCoastHint":"Detach early and watch the rotation settle. Reconnect from another angle if needed.","contentDetachedHint":"The vessel keeps coasting after release. Watch hull, heading and motion; reconnect at the bow if needed.","contentInertiaGuide":"The towed hull is long and heavy. It keeps moving after the tug stops. Turn wide and watch the stern. Detach and reconnect from another angle if stuck.","contentDockBraking":"The winch is braking. Press E to detach, then clear the hull so alignment can start.","contentDockAligning":"The tug is clear. The docking winch is aligning the hull."}}))Object.assign(rescueText[language],items);
for(const [language,items]of Object.entries({"ko":{"landingTitle":"임시 상륙장","landingBrief":"북쪽 수리장에 승객선이, 서쪽 적치장에 빈 부잔교가 남았습니다. 먼저 부잔교를 남동쪽 설치 구역으로 옮겨 내릴 길을 만드세요. 승객선을 먼저 동쪽으로 돌아 데려와 대기 포켓에 묶은 뒤 부잔교를 가져올 수도 있습니다.","landingPower":"부잔교와 승객선은 한 번에 한 척씩 예인합니다. 부잔교가 설치되기 전에는 승객을 내릴 수 없습니다. 전원을 끊어도 두 선체를 직접 정렬하면 완료할 수 있습니다.","landingLaunch":"수리장으로 출항","landingBoat":"수리장 승객선","landingPontoon":"이동식 부잔교","landingPassengerLine":"승객선 고정줄","landingPontoonLine":"부잔교 고정줄","landingHoldingPocket":"승객선 대기 포켓","landingInstallPocket":"부잔교 설치 구역","landingBoarding":"승객 상륙 선창","landingDrain":"적치장 배수 제어","landingMapLegend":"● 승객 ◆ 부잔교 □ 대기","landingUnmoor":"옮길 선체의 고정줄을 Q 삼각형으로 자르세요","landingChoose":"부잔교를 먼저 설치하거나, 승객선을 대기 포켓으로 옮기세요","landingTow":"안전한 상륙 길이 준비되면 승객선을 선창으로 옮기세요","landingTowPontoon":"부잔교를 남동쪽 설치 구역으로 옮기세요","landingPontoonHint":"설치 구역 안에서 느리게, 선수를 오른쪽으로 맞추세요. 전원이 있으면 윈치가 정렬을 돕습니다.","landingRouteHint":"안쪽 수로로 곧장 이동하거나, 동쪽을 돌아 대기 포켓에 먼저 묶을 수 있습니다.","landingCutHint":"승객선과 부잔교에 고정줄이 하나씩 있습니다. 절단 미리보기에서 대상과 전원을 확인하세요.","landingGuide":"빈 부잔교를 먼저 설치하고 승객선을 안쪽으로 데려오거나, 승객선을 동쪽으로 돌아 대기 포켓에 묶어 두고 부잔교를 가져오세요. 설치한 부잔교는 고정되며 다시 예인할 필요가 없습니다.","landingMissing":"부잔교가 아직 없습니다 · 먼저 설치해야 승객이 내릴 수 있습니다","landingReady":"상륙 길 준비 완료 · 승객선을 선창에 맞추세요","landingHeld":"승객선이 대기 중입니다 · 부잔교를 설치한 뒤 돌아오세요","landingHeldReady":"부잔교가 설치되었습니다 · 승객선 계류를 풀고 선창으로 옮기세요","landingCheckMissing":"부잔교 설치 필요","landingCheckReady":"부잔교 설치 완료","landingInstalled":"설치 완료","landingComplete":"명단 바깥의 이름들","landingOutcome":"부잔교가 끊긴 단차를 잇습니다. 마지막 승객들이 수리한 난간을 잡고 높은 선창으로 건너갑니다.","landingRecord":"06:30에 닫힌 명단은 대피의 끝이 아니었습니다. 06:47의 배는 누락된 이름들을 데리러 돌아왔습니다. 매옥의 배달판과 펌프 교대표, 수리장 작업표의 이름이 한 장에 모입니다.","landingArrival":["수리장 작업자","선창은 남았지만 건너갈 판이 떠내려갔어요. 서쪽 부잔교를 가져오면 이 사람들도 내려갈 수 있습니다."],"landingPassengerFree":["윤해수","승객선이 풀렸어. 부잔교가 준비되지 않았다면 대기 포켓에 잡아 두자."],"landingPontoonFree":["윤해수","부잔교가 풀렸어. 설치 구역으로 옮겨서 상륙 길을 만들자."],"landingYard":"해문 북부 수리장","landingWorkshop":"천막 공동 작업장","landingTools":"이름을 적어 둔 공용 공구","landingShelter":"높은 선창 / 임시 쉼터","landingNoBridge":"상륙 길 없음 · 부잔교 필요","chapterComplete":"다시 적은 항로의 기록","chapterBody":"선창에 도착한 사람들의 이름이 한 장의 명단에 채워졌습니다. 06:47은 늦은 출항이 아니라, 빠진 사람들을 데리러 돌아온 운항이었습니다. 윤해수는 젖은 무전기를 내려놓습니다. 이번 항로의 기록이 끝났습니다.","chapterDone":"항로의 마지막 기록 보기","chapterReplay":"임무 다시 출항","chapterReplayNote":"구조한 사람과 기록을 유지하며 완료한 임무를 독립적으로 다시 플레이할 수 있습니다.","investigation":"해문항 / 항로 기록","endingTagline":"명단 바깥의 이름들이\n선창에 도착했다.","endingIntro":"06:47은 늦은 출항이 아니었다.\n남겨진 이들을 데리러 돌아온 운항이었다.","endingStatus":"이번 항로 완료","endingRecord":"마지막 기록","credits":"만든 과정","creditsBody":"기획·글·Canvas 그림·코드는 이 프로젝트의 오리지널 제작이며 생성형 AI의 도움을 받았습니다.","creditsAudio":"효과음 샘플: Kenney — CC0. 음악과 항구 소리는 코드로 구성했습니다.","creditsRuntime":"오픈소스 실행 환경: Electron / Chromium. 전체 라이선스와 출처는 배포본의 LICENSE-NOTICES.md와 LICENSE 파일에 있습니다.","creditsScope":"현재는 개발 중인 짧은 게임입니다. Steam 정식 출시본이 아닙니다."},"en":{"landingTitle":"Temporary Landing","landingBrief":"A passenger boat waits in the northern repair yard, and an empty access pontoon in western storage. Install the pontoon in the southeastern outline to make a landing. Or bring the passengers around the east, moor them in the holding pocket, then fetch the pontoon.","landingPower":"Tow one hull at a time. Passengers cannot disembark until the pontoon is installed. With shared power cut, manually aligning both hulls still completes the job.","landingLaunch":"Depart for the repair yard","landingBoat":"Repair-yard passenger boat","landingPontoon":"Access pontoon","landingPassengerLine":"Passenger mooring line","landingPontoonLine":"Pontoon mooring line","landingHoldingPocket":"Passenger holding pocket","landingInstallPocket":"Pontoon installation outline","landingBoarding":"Passenger landing berth","landingDrain":"Yard drain control","landingMapLegend":"● People ◆ Pontoon □ Hold","landingUnmoor":"Cut the chosen hull's mooring line with a Q triangle","landingChoose":"Install the pontoon first, or bring the passengers to the holding pocket","landingTow":"Bring the passengers to the berth once a safe landing is ready","landingTowPontoon":"Tow the pontoon into its southeastern installation outline","landingPontoonHint":"Fit the whole pontoon inside, slow down and point right. With power, the winch can help align it.","landingRouteHint":"Use the inner channel, or bring the passengers around the east to the holding pocket first.","landingCutHint":"Each hull has one mooring line. Check the exact line and shared power in the cut preview.","landingGuide":"Install the pontoon first, then bring the passengers through the inner channel. Or tow the passengers around the east, moor them in the holding pocket, and fetch the pontoon. Once installed, the pontoon stays secured and needs no further towing.","landingMissing":"No access pontoon yet · install it before passengers can disembark","landingReady":"Landing ready · align the passenger boat in its berth","landingHeld":"Passengers are moored · install the pontoon, then return","landingHeldReady":"Pontoon installed · release the passengers' mooring and bring them to the berth","landingCheckMissing":"Pontoon still needed","landingCheckReady":"Pontoon installed","landingInstalled":"Installed","landingComplete":"The names outside the list","landingOutcome":"The pontoon bridges the broken approach. The passengers grip the patched railing and cross to the high pier.","landingRecord":"Closing the list at 06:30 did not end the evacuation. The 06:47 boat came back for the omitted people. Mae-ok's delivery board, the pump roster and the repair-yard work list finally share one page.","landingArrival":["Repair-yard worker","The high pier survived, but the access deck broke away. Bring the western pontoon and these people can cross."],"landingPassengerFree":["Yoon Haesu","Passenger boat free. If the pontoon is not ready, we can hold them in the pocket."],"landingPontoonFree":["Yoon Haesu","Pontoon free. Bring it to the installation outline and make a landing."],"landingYard":"HAEMUN NORTH REPAIR YARD","landingWorkshop":"SHARED TENT WORKSHOP","landingTools":"NAMES ON SHARED TOOLS","landingShelter":"HIGH PIER / SHELTER","landingNoBridge":"NO ACCESS · PONTOON NEEDED","chapterComplete":"The route, written again","chapterBody":"The names of the people who reached the pier fill one page. 06:47 was not a late departure. It was a return for the people left off the list. Yoon Haesu puts down the wet radio. The record of this route is complete.","chapterDone":"Read the final route record","chapterReplay":"Replay a departure","chapterReplayNote":"Keep the people and records already saved, and replay completed jobs as independent departures.","investigation":"HAEMUN / ROUTE RECORD","endingTagline":"The names outside the list\nhave reached the pier.","endingIntro":"06:47 was not a late departure.\nIt was a return for those left behind.","endingStatus":"This route is complete","endingRecord":"Final record","credits":"Credits","creditsBody":"Original game design, writing, Canvas artwork and code, developed with generative AI assistance.","creditsAudio":"Sound samples: Kenney — CC0. Music and harbor ambience are composed in code.","creditsRuntime":"Open-source runtime: Electron / Chromium. Full provenance and license notices are included in LICENSE-NOTICES.md and the distribution's LICENSE files.","creditsScope":"This is a short development build, not a commercial Steam release."}})){for(const [key,value]of Object.entries(items)){if(Array.isArray(value))rescueText[language].radio[key]=value;else rescueText[language][key]=value;}}
