Object.assign(rescueText.ko.radio,{engineerCall:['Park','노란 작업등 아래 정비대예요. 내 주위에 부표 세 개로 구조망을 펼쳐 주세요. 아래쪽 철판은 피하고요.'],operatorCall:['Woo','동쪽 갑문실 창가입니다. 내 주위를 부표 세 개로 감싸 주면 내려갈 수 있어요. 아래 문은 피하세요.']});
Object.assign(rescueText.en.radio,{engineerCall:['Park','The work platform under the yellow lamp. Place three buoys around me for a rescue net. Avoid the plates below.'],operatorCall:['Woo','At the eastern lock-room window. Put three buoys around me so I can come down. Avoid the lower gate.']});
